ST.xhtml:p:
(*来了可燃气输出的上升沿就开启可燃气电源*)
RTrigger_OpenCombustible(CLK := g_boCombustibleValve ); 
IF  RTrigger_OpenCombustible.Q THEN
  g_boCombustibleValvePower:=g_boCombustibleValve;
END_IF;

(*来了空气输出的上升沿就开启空气电源*)
RTrigger_OpenOxidizing(CLK := g_boOxidizingValve ); 
IF  RTrigger_OpenOxidizing.Q THEN
  g_boOxidizingValvePower:=g_boOxidizingValve;
END_IF;

RTrigger_CloseGasPower(CLK := g_bProcessDone ); 
IF bcloseGasPower AND  RTrigger_CloseGasPower.Q THEN
  g_boCombustibleValvePower:=FALSE;
  g_boOxidizingValvePower:=FALSE;
END_IF;
